if(EditorApplication.isPlaying||Lightmapping.isRunning)throw new System.Exception("Stopped editor and completed bake required");
var report=new System.Collections.Generic.List<string>();System.Action<bool,string> check=(ok,msg)=>report.Add((ok?"PASS ":"FAIL ")+msg);
var mesh=GameObject.Find("QuarryEnvironment/PolishedStone").GetComponent<MeshFilter>().sharedMesh;var v=mesh.vertices;var t=mesh.triangles;var uv=mesh.uv;bool bounded=true;int top=0;
for(int i=0;i<t.Length;i+=3)if(Mathf.Abs(v[t[i]].y-.005f)<.0001f&&Mathf.Abs(v[t[i+1]].y-.005f)<.0001f&&Mathf.Abs(v[t[i+2]].y-.005f)<.0001f){top++;for(int j=0;j<3;j++){var p=uv[t[i+j]];bounded&=p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1;}}
check(top==378&&bounded,"All 378 paving top triangles stay within stone atlas UV bounds");
bool unique=true;int sampled=0;for(float x=-6.13f;x<8;x+=.29f)for(float z=-7.73f;z<1.35f;z+=.31f){int overlaps=0;var p=new Vector2(x,z);for(int i=0;i<t.Length;i+=3){var a=v[t[i]];var b=v[t[i+1]];var c=v[t[i+2]];if(Mathf.Abs(a.y-.005f)>.0001f||Mathf.Abs(b.y-.005f)>.0001f||Mathf.Abs(c.y-.005f)>.0001f)continue;Vector2 aa=new Vector2(a.x,a.z),bb=new Vector2(b.x,b.z),cc=new Vector2(c.x,c.z);float cross(Vector2 q,Vector2 r)=>q.x*r.y-q.y*r.x;float area=cross(bb-aa,cc-aa);float u=cross(bb-p,cc-p)/area,w=cross(cc-p,aa-p)/area,h=1-u-w;if(u>1e-5f&&w>1e-5f&&h>1e-5f)overlaps++;}unique&=overlaps<=1;sampled++;}
check(unique,"No overlapping paving faces at "+sampled+" interior samples");
check(!GameObject.Find("PlayerTestYard/Ground").GetComponent<Renderer>().enabled&&!GameObject.Find("MiningProductionSite/Textured Quarry Ground").GetComponent<Renderer>().enabled,"Redundant ground renderers remain hidden; colliders retained");
var prod=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MiningProduction>();var zones=new[]{prod.inputZone,prod.outputZone,prod.sellZone};check(zones.All(z=>z.enabled&&z.isTrigger),"All three production triggers remain enabled");check(zones.Select(z=>z.GetComponentsInChildren<MeshRenderer>().First(r=>r.name=="Border").sharedMaterial).Distinct().Count()==3,"Each station has a distinct shared paint material");
check(!prod.orderLabel.gameObject.activeSelf,"Oversized duplicate delivery text hidden");var guide=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.QuarryGuidance>();check(!guide.stepLabel.gameObject.activeSelf&&!guide.progress.gameObject.activeSelf,"Redundant guide step/progress widgets hidden");check(!guide.dialogGroup.blocksRaycasts,"Guide remains nonblocking");
var rocks=UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None);check(rocks.Length==78&&rocks.Count(r=>r.naturalBoulder)==12,"All gameplay rocks and natural pilot preserved");check(rocks.All(r=>(GameObjectUtility.GetStaticEditorFlags(r.rockRenderer.gameObject)&StaticEditorFlags.ContributeGI)==0),"Destructible rocks do not leave permanent baked shadows");
check(Lightmapping.lightingDataAsset&&LightmapSettings.lightmaps.Length==1&&GameObject.Find("QuarryEnvironment/PolishedStone").GetComponent<Renderer>().lightmapIndex==0,"Fresh bake includes repaired paving in one lightmap");check(UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Length==4,"Existing four lights retained; no added runtime light");
report.Add("BUDGET paving/environment stone mesh="+mesh.triangles.Length/3+" triangles; lightmap="+LightmapSettings.lightmaps[0].lightmapColor.width+"px; 3 shared station paint materials; no new texture atlas");System.IO.File.WriteAllLines("Maintenance/Miner/environment-static-verification.txt",report);return string.Join("\n",report);
